def transform(grid):
    """Draw a full-width color-3 divider in the empty row between color-2 parts."""
    out = [row[:] for row in grid]
    h = len(out)
    for r in range(h):
        if all(v == 0 for v in out[r]):
            has_above = any(any(v != 0 for v in out[i]) for i in range(r))
            has_below = any(any(v != 0 for v in out[i]) for i in range(r + 1, h))
            if has_above and has_below:
                out[r] = [3] * len(out[r])
                break
    return out
